package driver

import (
	"io"

	"kigumi/internal/compiler/sem"
	"kigumi/internal/compiler/syntax"
	"kigumi/internal/lang/token"
	buildconfig "kigumi/internal/toolchain/config"
	"kigumi/internal/toolchain/module"
	"kigumi/internal/toolchain/policy"
)

// Package is one directory of .kg files; Path is the canonical import path relative to the module root, with std packages carrying the "std/" prefix.
type Package struct {
	Path  string
	Dir   string
	Files []*syntax.Tree
	// Std marks declaration stubs: bodiless functions are allowed there.
	Std bool
	// Header marks a package generated by a Header import; like Std, it stays in an explicit entry's diagnostic scope even when unimported.
	Header bool
	// Module is the dependency the package came from; "" for the module
	// being built.
	Module string
}

// Module is a module root plus the std stubs it can import.
type Module struct {
	Root string
	// Name is the module name from mod.kg; it prefixes the import paths of
	// the module's own packages. "" for a manifest-less directory.
	Name  string
	Entry string
	// ExplicitEntry marks that the caller picked one root rather than the whole module; it narrows checking to that entry's build scope.
	ExplicitEntry bool
	overlay       map[string][]byte
	// diagsReported marks that reportDiagnostics already wrote m's diagnostics once, so a build's later compile() call skips the write shared.Load made.
	diagsReported bool
	// FileStore numbers every parsed source so diagnostics can point
	// across files.
	FileStore *token.SourceStore
	stats     Stats
	// lastAnalysis is the most recent Analyze result, for a post-build
	// report (ResourceReport) that would otherwise need to re-lower the module.
	lastAnalysis *Analysis
	Packages     map[string]*Package
	// Order lists package paths sorted for deterministic iteration.
	Order []string
	// Links and Sources collect the C libraries and sources of the module
	// and its dependencies, search paths and sources made absolute.
	Links   []module.Link
	Sources []string
	// Manifest is mod.kg, or the leading records of the script.
	Manifest module.ModFile
	// Selected is what minimal version selection chose for each dependency.
	Selected map[string]module.Require
	// ScriptFile is the root-relative entry that carried the manifest.
	ScriptFile string
	// Violations are release-policy findings from loading (a local replacement,
	// an unresolved native Link); policy.Evaluate classifies each under a BuildPolicy.
	Violations []policy.Violation
	// UnusedReplaces are development warnings for Replace records that match nothing in the graph.
	UnusedReplaces []policy.Violation
	// depInterrupt are the dependencies' Interrupt records, in the order the dependencies were loaded.
	depInterrupt []sem.DepInterrupt
	local        module.Local
	target       buildconfig.Target
	headers      headerLibc
	// deny, ceiling and artifactName carry an artifact's declared
	// availability (LoadOptions) through to semModule (check.go).
	deny          []string
	ceiling       string
	artifactName  string
	nestedModules []string
	// explicitZig is $KIGUMI_ZIG (LoadOptions.ZigPath), read only by
	// internal/cli; ResolveZig tries it before PATH.
	explicitZig string
	// Carry LoadOptions' same-named fields to ResolveZig's on-demand fetch.
	zigHome      string
	zigIndexURL  string
	zigPublicKey string
	offline      bool
	zigNotice    io.Writer
	verifyPasses bool
	lowerAll     bool
	fileOrder    func(names []string)
	compiler     buildconfig.CompilerOptions
	// opts is the load this module came from, so a reload for an artifact or a
	// plan keeps the policy and toolchain flags the first load honored.
	opts        LoadOptions
	index       *pkgIndex
	idxStats    IndexStats
	rootDirs    []string
	rootImports []string
	allPackages bool
	allOwn      bool
	// deferred marks a load whose reachable packages are not parsed yet (ensureParsed).
	deferred bool
	loadErr  error
	pkgCache *packageCache
	test     bool
	settled  *settledCheck
	// keyEntry and keyExplicit are the entry as loaded; semModule may fill m.Entry in later.
	keyEntry    string
	keyExplicit bool
	cancel      func() bool
	pkgStatus   []PackageStatus
	unitCheck   bool
	lazyStd     bool
	unitStats   UnitStats
	// session shares one analysis across Check/Run/Build; nil until attached.
	session *CompilationSession
	// parseSnapshot caches ParseSnapshot for the current package set.
	parseSnapshot  *syntax.ParseSnapshot
	parsedPackages int
}

// cwdFor is the directory a run uses: the run's own choice, else the options'.
func (m *Module) cwdFor(own string) string {
	if own != "" {
		return own
	}
	return m.compiler.Cwd
}
